// Scenario C: an INTENTIONALLY FAILING test whose report REALLY contains a credential. The pipeline's scan must reject it and the upload must be skipped.
// The "credential" is a random canary generated by the workflow for this run only (PROOF_CANARY), never a real secret and never written in this repository. It is sent three ways, because a trace
// records request headers, query strings and bodies: an Authorization header, a query-string token, and a password in the body. The target does not exist; only the recorded request matters.
const { test, expect } = require('@playwright/test');

test('proof C: sends a canary credential, then fails on purpose, so the report contains it', async ({ request }) => {
  const canary = process.env.PROOF_CANARY;
  expect(canary && canary.length >= 24, 'the workflow must provide a random PROOF_CANARY').toBeTruthy();
  await request.post('/api/proof-canary?access_token=' + canary, { headers: { Authorization: 'Bearer ' + canary }, data: { username: 'proof-user', password: canary }, failOnStatusCode: false });
  expect(1, 'INTENTIONAL FAILURE for the artifact pipeline proof').toBe(2);
});
